                    <v-img
                      :src="getImageUrl(chat)"
                      :lazy-src="defaultAvatar"
                      aspect-ratio="1"
                      class="avatar-image-full"
                    >
                      <template v-slot:placeholder>
                        <v-row class="fill-height ma-0" align="center" justify="center">
