                      </template>
                      <template v-slot:error>
                        <v-row class="fill-height ma-0" align="center" justify="center">
                          <v-icon size="36" color="grey lighten-1">mdi-account</v-icon>
                        </v-row>
                      </template>
                    </v-img>
                </v-list-item-avatar>

                <!-- Content Section -->
                <v-list-item-content class="chat-content-full">
