                    >
                      <v-icon x-small left>
                        {{ isSentByMe(chat) ? 'mdi-send' : 'mdi-receive' }}
                      </v-icon>
                      {{ isSentByMe(chat) ? 'Sent' : 'Received' }}
                    </v-chip>

                    <v-spacer></v-spacer>

                    <v-btn
