<script>
import serverUrl from '../../config'
import axios from 'axios';
import io from "socket.io-client";

export default {
  name: 'ChatListFull',

  data() {
    return {
      socket: io(serverUrl, {
        query: { token: localStorage.getItem("token") },
      }),
      recent: [],
      urls: serverUrl,
      defaultAvatar: require('@/assets/avatar.png'),
      userId: localStorage.getItem('userID'),
      searchQuery: '',
      showSearch: false,

      // Snackbar
      snackbar: false,
      snackbarText: '',
      snackbarColor: 'success',
      snackbarIcon: 'mdi-check-circle',
    };
  },

  computed: {
    filteredChats() {
      if (!this.searchQuery) return this.recent;
      const query = this.searchQuery.toLowerCase();
      return this.recent.filter(chat => {
        const name = this.getChatName(chat).toLowerCase();
        const text = (chat.text || '').toLowerCase();
        return name.includes(query) || text.includes(query);
      });
    }
  },

  created() {
    this.loadMessages();

    this.socket.emit('some', 'some');

    this.socket.on("new-msg-list", (msg) => {
      this.handleNewMessage(msg);
    });

    this.socket.on("new-msg-list2", (msg) => {
      this.handleNewMessage(msg);
    });

  },

  methods: {
    loadMessages() {
      axios.get(this.urls + "/get-all-messages", {
        headers: { authorization: localStorage.getItem("token") },
      }).then((res) => {
        var ret = [];
        for (var i = res.data.length - 1; i >= 0; i--) {
          ret.push(res.data[i]);
        }
        this.recent = ret;
        console.log(this.recent)
        this.sortArrayByDate(this.recent);

        
      });
    },

   handleNewMessage(msg) {
  console.log('Raw message:', msg);
  
  // تطبيع البيانات: تحويل from/to إلى كائنات موحدة
  const normalizedMsg = {
    ...msg,
    from: typeof msg.from === 'object' && msg.from !== null 
      ? msg.from 
      : { _id: msg.from, name: 'Unknown' },
    to: typeof msg.to === 'object' && msg.to !== null 
      ? msg.to 
      : { _id: msg.to, name: 'Unknown' }
  };
  
  console.log('Normalized:', normalizedMsg);
  
  const msgOtherId = this.getOtherId(normalizedMsg);
  
  if (!msgOtherId) {
    console.error('Could not determine other ID');
    return;
  }
  
  const existingIndex = this.recent.findIndex(chat => 
    this.getOtherId(chat) === msgOtherId
  );
  
  if (existingIndex !== -1) {
    // تحديث المحادثة الموجودة
    this.recent[existingIndex].text = normalizedMsg.text;
    this.recent[existingIndex].date = normalizedMsg.date;
    this.recent[existingIndex].from = normalizedMsg.from;
    this.recent[existingIndex].to = normalizedMsg.to;
    this.recent[existingIndex].read = false;
  } else {
    this.recent.push(normalizedMsg);
  }
  
  this.sortArrayByDate(this.recent);
  this.showSnackbar('New message received!', 'info', 'mdi-message-alert');
},

    refreshMessages() {
      this.loadMessages();
      this.showSnackbar('Messages refreshed', 'success', 'mdi-refresh');
    },

    deleteChat(chatId) {
      const index = this.recent.findIndex(c => c._id === chatId);
      if (index > -1) {
        this.recent.splice(index, 1);
        this.showSnackbar('Conversation removed', 'info', 'mdi-delete');
      }
    },

    getImageUrl(chat) {
      try {
        const otherId = this.getOtherId(chat);
        if (!otherId) return this.defaultAvatar;
        return `${this.urls}/profile-image/${otherId}.PNG`;
      } catch (error) {
        return this.defaultAvatar;
      }
    },

    getOtherId(chat) {
  if (!chat) return null;
  
  // التعامل مع from (قد يكون كائن أو نص)
  let fromId, toId;
  
  if (typeof chat.from === 'object' && chat.from !== null) {
    fromId = chat.from._id;
  } else {
    fromId = chat.from;
  }
  
  // التعامل مع to (قد يكون كائن أو نص)
  if (typeof chat.to === 'object' && chat.to !== null) {
    toId = chat.to._id;
  } else {
    toId = chat.to;
  }
  
  if (!fromId || !toId) {
    console.warn('Missing from/to in chat:', { from: chat.from, to: chat.to });
    return null;
  }
  
  const myId = String(this.userId);
  const fromIdStr = String(fromId);
  const toIdStr = String(toId);
  
  console.log('getOtherId:', { myId, fromIdStr, toIdStr, result: fromIdStr === myId ? toIdStr : fromIdStr });
  
  if (fromIdStr === myId) return toIdStr;
  else return fromIdStr;
},

    getChatName(chat) {
  if (!chat) return 'Unknown';
  
  let fromId, fromName, toId, toName;
  
  console.log(toId)
  // استخراج from
  if (typeof chat.from === 'object' && chat.from !== null) {
    fromId = chat.from._id;
    fromName = chat.from.name;
  } else {
    fromId = chat.from;
    fromName = 'Unknown';
  }
  
  // استخراج to
  if (typeof chat.to === 'object' && chat.to !== null) {
    toId = chat.to._id;
    toName = chat.to.name;
  } else {
    toId = chat.to;
    toName = 'Unknown';
  }
  
  const myId = String(this.userId);
  
  if (String(fromId) === myId) {
    return toName || 'Unknown';
  } else {
    return fromName || 'Unknown';
  }
},

    isSentByMe(chat) {
  if (!chat) return false;
  
  let fromId;
  if (typeof chat.from === 'object' && chat.from !== null) {
    fromId = chat.from._id;
  } else {
    fromId = chat.from;
  }
  
  return String(fromId) === String(this.userId);
},

    getDirectionColor(chat) {
      return this.isSentByMe(chat) ? 'primary' : 'success';
    },

    formatTime(date) {
      if (!date) return 'Just now';
      const d = new Date(date);
      const now = new Date();
      const diff = Math.floor((now - d) / 1000);

      if (diff < 60) return 'Just now';
      if (diff < 3600) return Math.floor(diff / 60) + 'm';
      if (diff < 86400) return Math.floor(diff / 3600) + 'h';
      if (diff < 604800) return Math.floor(diff / 86400) + 'd';
      return d.toLocaleDateString();
    },

    sortArrayByDate(arr) {
      arr.sort(function(a, b) {
        var c = new Date(a.date);
        var d = new Date(b.date);
        return d - c;
      });
    },

    openNewMessage(firstId, secondId) {
      console.log('first: ',firstId,' seconde: ', secondId)
      const targetId = String(this.userId) === String(secondId) ? firstId : secondId;
      this.$router.push({ 
        name: 'private-chat', 
        params: { receiverID: targetId } 
      });
    },

    showSnackbar(text, color, icon) {
      this.snackbarText = text;
      this.snackbarColor = color;
      this.snackbarIcon = icon;
      this.snackbar = true;
    }
  }
};
</script>

